"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[49223],{76297(n,r,e){e.r(r),e.d(r,{assets:()=>E,contentTitle:()=>_,default:()=>t,frontMatter:()=>i,metadata:()=>a,toc:()=>l});const a=JSON.parse('{"id":"cursos/oracle/modulos/sql-dinamico/respuesta","title":"respuesta","description":"Respuesta 2: Creaci\xf3n Din\xe1mica de Tabla de Respaldo","source":"@site/docs/cursos/oracle/modulos/16-sql-dinamico/respuesta.md","sourceDirName":"cursos/oracle/modulos/16-sql-dinamico","slug":"/cursos/oracle/modulos/sql-dinamico/respuesta","permalink":"/sasf-temarios/cursos/oracle/modulos/sql-dinamico/respuesta","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"private":true,"sidebar_class_name":"private","sidebar_label":"Soluciones"},"sidebar":"cursosSidebar","previous":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/oracle/modulos/sql-dinamico/ejercicio"},"next":{"title":"Clase","permalink":"/sasf-temarios/cursos/oracle/modulos/procedimientos-funciones/clase"}}');var s=e(74848),o=e(28453);const i={private:!0,sidebar_class_name:"private",sidebar_label:"Soluciones"},_=void 0,E={},l=[{value:"Respuesta 2: Creaci\xf3n Din\xe1mica de Tabla de Respaldo",id:"respuesta-2-creaci\xf3n-din\xe1mica-de-tabla-de-respaldo",level:3},{value:"Respuesta 3: SELECT Din\xe1mico con Validaci\xf3n de Metadatos",id:"respuesta-3-select-din\xe1mico-con-validaci\xf3n-de-metadatos",level:3},{value:"Respuesta 4: OPEN FOR Din\xe1mico con Filtro por Especialidad",id:"respuesta-4-open-for-din\xe1mico-con-filtro-por-especialidad",level:3},{value:"Respuesta 6: Sin\xf3nimos y consulta remota",id:"respuesta-6-sin\xf3nimos-y-consulta-remota",level:3}];function c(n){const r={code:"code",h3:"h3",hr:"hr",pre:"pre",...(0,o.R)(),...n.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(r.h3,{id:"respuesta-2-creaci\xf3n-din\xe1mica-de-tabla-de-respaldo",children:"Respuesta 2: Creaci\xf3n Din\xe1mica de Tabla de Respaldo"}),"\n",(0,s.jsx)(r.pre,{children:(0,s.jsx)(r.code,{className:"language-sql",children:"DECLARE\r\n    v_fecha VARCHAR2(8) := '20260101';\r\n    v_nombre_tabla VARCHAR2(60);\r\n    v_sql  VARCHAR2(500);\r\n    v_existe NUMBER;\r\nBEGIN\r\n    v_nombre_tabla := 'PACIENTES_' || v_fecha;\r\n\r\n    -- Verificar si la tabla ya existe\r\n    SELECT COUNT(*)\r\n    INTO v_existe\r\n    FROM user_tables\r\n    WHERE table_name = UPPER(v_nombre_tabla);\r\n\r\n    IF v_existe > 0 THEN\r\n        v_sql := 'DROP TABLE ' || v_nombre_tabla;\r\n        EXECUTE IMMEDIATE v_sql;\r\n        DBMS_OUTPUT.PUT_LINE('Tabla ' || v_nombre_tabla || ' eliminada.');\r\n    END IF;\r\n\r\n    -- Crear tabla de respaldo\r\n    v_sql := 'CREATE TABLE ' || v_nombre_tabla ||\r\n             ' AS SELECT * FROM PACIENTES';\r\n    EXECUTE IMMEDIATE v_sql;\r\n\r\n    DBMS_OUTPUT.PUT_LINE('Respaldo creado: ' || v_nombre_tabla);\r\n    DBMS_OUTPUT.PUT_LINE('Registros copiados: ' || SQL%ROWCOUNT);\r\nEXCEPTION\r\n    WHEN OTHERS THEN\r\n        DBMS_OUTPUT.PUT_LINE('Error: ' || SQLERRM);\r\nEND;\r\n/\r\n\r\n-- Verificar\r\nSELECT table_name FROM user_tables WHERE table_name LIKE 'PACIENTES_%';\n"})}),"\n",(0,s.jsx)(r.hr,{}),"\n",(0,s.jsx)(r.h3,{id:"respuesta-3-select-din\xe1mico-con-validaci\xf3n-de-metadatos",children:"Respuesta 3: SELECT Din\xe1mico con Validaci\xf3n de Metadatos"}),"\n",(0,s.jsx)(r.pre,{children:(0,s.jsx)(r.code,{className:"language-sql",children:"CREATE OR REPLACE PROCEDURE p_consultar_dinamico(\r\n    p_tabla   VARCHAR2,\r\n    p_columna VARCHAR2,\r\n    p_valor   VARCHAR2\r\n) IS\r\n    v_sql        VARCHAR2(500);\r\n    v_cursor     SYS_REFCURSOR;\r\n    v_valor_tipeado VARCHAR2(4000);\r\n    v_columna_existe NUMBER;\r\n    v_tabla_existe   NUMBER;\r\nBEGIN\r\n    -- =============================================\r\n    -- \xbfPor qu\xe9 tabla y columna NO pueden bindearse?\r\n    -- Las bind variables (:var) en Oracle solo\r\n    -- reemplazan VALORES literales, no identificadores\r\n    -- de esquema. Los nombres de tabla/columna son\r\n    -- parte del parse tree y deben conocerse en\r\n    -- tiempo de compilaci\xf3n del cursor.\r\n    -- Para usarlos din\xe1micamente debemos concatenar\r\n    -- (con las debidas validaciones de seguridad).\r\n    -- =============================================\r\n\r\n    -- Validar que la tabla exista\r\n    SELECT COUNT(*)\r\n    INTO v_tabla_existe\r\n    FROM user_tables\r\n    WHERE table_name = UPPER(p_tabla);\r\n\r\n    IF v_tabla_existe = 0 THEN\r\n        RAISE_APPLICATION_ERROR(-20001, 'Tabla \"' || p_tabla || '\" no existe.');\r\n    END IF;\r\n\r\n    -- Validar que la columna exista en la tabla\r\n    SELECT COUNT(*)\r\n    INTO v_columna_existe\r\n    FROM user_tab_columns\r\n    WHERE table_name  = UPPER(p_tabla)\r\n      AND column_name = UPPER(p_columna);\r\n\r\n    IF v_columna_existe = 0 THEN\r\n        RAISE_APPLICATION_ERROR(-20002, 'Columna \"' || p_columna ||\r\n                                '\" no existe en tabla \"' || p_tabla || '\".');\r\n    END IF;\r\n\r\n    -- Construir y ejecutar SELECT din\xe1mico\r\n    v_sql := 'SELECT * FROM ' || UPPER(p_tabla) ||\r\n             ' WHERE ' || UPPER(p_columna) || ' = :val';\r\n\r\n    EXECUTE IMMEDIATE v_sql USING p_valor;\r\n\r\n    DBMS_OUTPUT.PUT_LINE('Consulta ejecutada: ' || v_sql);\r\n    DBMS_OUTPUT.PUT_LINE('Valor buscado: ' || p_valor);\r\n    DBMS_OUTPUT.PUT_LINE('Filas encontradas: ' || SQL%ROWCOUNT);\r\n\r\nEXCEPTION\r\n    WHEN NO_DATA_FOUND THEN\r\n        DBMS_OUTPUT.PUT_LINE('No se encontraron registros con ' ||\r\n                             p_columna || ' = ' || p_valor);\r\n    WHEN TOO_MANY_ROWS THEN\r\n        DBMS_OUTPUT.PUT_LINE('Se encontraron m\xfaltiples registros.');\r\n    WHEN OTHERS THEN\r\n        DBMS_OUTPUT.PUT_LINE('Error: ' || SQLERRM);\r\nEND;\r\n/\r\n\r\n-- Pruebas\r\nBEGIN\r\n    p_consultar_dinamico('PACIENTES', 'nombre', 'Ana Mart\xednez');\r\n    DBMS_OUTPUT.PUT_LINE('---');\r\n    p_consultar_dinamico('PACIENTES', 'id', '1');\r\n    DBMS_OUTPUT.PUT_LINE('---');\r\n    p_consultar_dinamico('PACIENTES', 'email', 'no_existe@email.com');\r\nEND;\r\n/\n"})}),"\n",(0,s.jsx)(r.hr,{}),"\n",(0,s.jsx)(r.h3,{id:"respuesta-4-open-for-din\xe1mico-con-filtro-por-especialidad",children:"Respuesta 4: OPEN FOR Din\xe1mico con Filtro por Especialidad"}),"\n",(0,s.jsx)(r.pre,{children:(0,s.jsx)(r.code,{className:"language-sql",children:"-- ============================================\r\n-- Funci\xf3n con OPEN FOR din\xe1mico\r\n-- ============================================\r\nCREATE OR REPLACE FUNCTION f_medicos_por_especialidad(\r\n    p_especialidad VARCHAR2\r\n) RETURN SYS_REFCURSOR IS\r\n    v_cursor SYS_REFCURSOR;\r\n    v_sql    VARCHAR2(500);\r\nBEGIN\r\n    v_sql := 'SELECT m.id           AS medico_id,\r\n                     m.nombre       AS medico_nombre,\r\n                     COUNT(c.id)    AS total_citas,\r\n                     MAX(c.fecha_cita) AS ultima_cita\r\n              FROM MEDICOS m\r\n              LEFT JOIN CITAS c ON c.medico_id = m.id\r\n              WHERE m.especialidad = :esp\r\n              GROUP BY m.id, m.nombre\r\n              ORDER BY COUNT(c.id) DESC';\r\n\r\n    OPEN v_cursor FOR v_sql USING p_especialidad;\r\n    RETURN v_cursor;\r\nEND;\r\n/\r\n\r\n-- ============================================\r\n-- Bloque an\xf3nimo de prueba\r\n-- ============================================\r\nDECLARE\r\n    v_cursor   SYS_REFCURSOR;\r\n    v_med_id   MEDICOS.id%TYPE;\r\n    v_med_nom  MEDICOS.nombre%TYPE;\r\n    v_total    NUMBER;\r\n    v_ultima   DATE;\r\nBEGIN\r\n    v_cursor := f_medicos_por_especialidad('Cardiolog\xeda');\r\n\r\n    DBMS_OUTPUT.PUT_LINE('=== M?DICOS DE CARDIOLOG\xcdA ===');\r\n    DBMS_OUTPUT.PUT_LINE('');\r\n\r\n    LOOP\r\n        FETCH v_cursor INTO v_med_id, v_med_nom, v_total, v_ultima;\r\n        EXIT WHEN v_cursor%NOTFOUND;\r\n\r\n        DBMS_OUTPUT.PUT_LINE(\r\n            RPAD(v_med_nom, 25) || ' | Citas: ' ||\r\n            RPAD(TO_CHAR(v_total), 4) || ' | Revisarltima: ' ||\r\n            NVL(TO_CHAR(v_ultima, 'DD/MM/YYYY'), 'Sin citas')\r\n        );\r\n    END LOOP;\r\n\r\n    CLOSE v_cursor;\r\nEND;\r\n/\r\n\r\n---\r\n\r\n### Respuesta 5: DBMS_SQL \u2014 Consulta con columnas din\xe1micas\r\n\r\n```sql\r\nDECLARE\r\n    v_cursor     NUMBER;\r\n    v_sql        VARCHAR2(500);\r\n    v_desc_tab   DBMS_SQL.DESC_TAB;\r\n    v_columnas   NUMBER;\r\n    v_filas      NUMBER;\r\n    v_valor      VARCHAR2(4000);\r\n    v_resultado  BOOLEAN;\r\nBEGIN\r\n    v_sql := 'SELECT id, nombre, fecha_nacimiento, telefono, email FROM PACIENTES';\r\n    v_cursor := DBMS_SQL.OPEN_CURSOR;\r\n\r\n    -- Parsear la sentencia\r\n    DBMS_SQL.PARSE(v_cursor, v_sql, DBMS_SQL.NATIVE);\r\n\r\n    -- Describir columnas (descubrir estructura din\xe1micamente)\r\n    DBMS_SQL.DESCRIBE_COLUMNS(v_cursor, v_columnas, v_desc_tab);\r\n\r\n    DBMS_OUTPUT.PUT_LINE('Columnas descubiertas: ' || v_columnas);\r\n    DBMS_OUTPUT.PUT_LINE('');\r\n\r\n    -- Definir cada columna como VARCHAR2\r\n    FOR i IN 1..v_columnas LOOP\r\n        DBMS_OUTPUT.PUT_LINE('  Col ' || i || ': ' ||\r\n                             RPAD(v_desc_tab(i).col_name, 25) || ' (' ||\r\n                             v_desc_tab(i).col_type || ')');\r\n        DBMS_SQL.DEFINE_COLUMN(v_cursor, i, v_valor, 4000);\r\n    END LOOP;\r\n\r\n    -- Ejecutar y hacer fetch\r\n    v_filas := DBMS_SQL.EXECUTE(v_cursor);\r\n\r\n    DBMS_OUTPUT.PUT_LINE('');\r\n    DBMS_OUTPUT.PUT_LINE('=== DATOS ===');\r\n\r\n    LOOP\r\n        v_resultado := DBMS_SQL.FETCH_ROWS(v_cursor) > 0;\r\n        EXIT WHEN NOT v_resultado;\r\n\r\n        -- Obtener valores de cada columna\r\n        FOR i IN 1..v_columnas LOOP\r\n            DBMS_SQL.COLUMN_VALUE(v_cursor, i, v_valor);\r\n            DBMS_OUTPUT.PUT_LINE(RPAD(v_desc_tab(i).col_name, 25) || ': ' || v_valor);\r\n        END LOOP;\r\n        DBMS_OUTPUT.PUT_LINE('------------------------------');\r\n    END LOOP;\r\n\r\n    DBMS_OUTPUT.PUT_LINE('Total filas: ' || v_filas);\r\n\r\n    -- Cerrar cursor\r\n    DBMS_SQL.CLOSE_CURSOR(v_cursor);\r\nEND;\r\n/\n"})}),"\n",(0,s.jsx)(r.hr,{}),"\n",(0,s.jsx)(r.h3,{id:"respuesta-6-sin\xf3nimos-y-consulta-remota",children:"Respuesta 6: Sin\xf3nimos y consulta remota"}),"\n",(0,s.jsx)(r.pre,{children:(0,s.jsx)(r.code,{className:"language-sql",children:"-- ============================================\r\n-- Crear sin\xf3nimo privado para tabla remota\r\n-- ============================================\r\nBEGIN\r\n    EXECUTE IMMEDIATE 'CREATE SYNONYM SYN_PACIENTES_REMOTO\r\n                       FOR PACIENTES@DBLINK_SUCURSAL';\r\n    DBMS_OUTPUT.PUT_LINE('Sin\xf3nimo SYN_PACIENTES_REMOTO creado.');\r\nEND;\r\n/\r\n\r\n-- ============================================\r\n-- Verificar sin\xf3nimo en el diccionario\r\n-- ============================================\r\nSELECT synonym_name, table_owner, table_name, db_link\r\nFROM user_synonyms\r\nWHERE synonym_name = 'SYN_PACIENTES_REMOTO';\r\n\r\n-- ============================================\r\n-- Consulta remota con EXECUTE IMMEDIATE\r\n-- ============================================\r\nDECLARE\r\n    v_sql   VARCHAR2(200);\r\n    v_total NUMBER;\r\nBEGIN\r\n    v_sql := 'SELECT COUNT(*) FROM PACIENTES@DBLINK_SUCURSAL';\r\n    EXECUTE IMMEDIATE v_sql INTO v_total;\r\n\r\n    DBMS_OUTPUT.PUT_LINE('Total pacientes en BD remota: ' || v_total);\r\nEND;\r\n/\r\n\r\n-- ============================================\r\n-- Sin\xf3nimo p\xfablico (requiere privilegio CREATE PUBLIC SYNONYM)\r\n-- ============================================\r\nBEGIN\r\n    EXECUTE IMMEDIATE 'CREATE PUBLIC SYNONYM PUBLIC_SYN_PACIENTES\r\n                       FOR PACIENTES';\r\n    DBMS_OUTPUT.PUT_LINE('Sin\xf3nimo p\xfablico PUBLIC_SYN_PACIENTES creado.');\r\nEND;\r\n/\r\n\r\n-- ============================================\r\n-- Verificar todos los sin\xf3nimos del esquema\r\n-- ============================================\r\nSELECT synonym_name, table_owner, table_name, db_link\r\nFROM user_synonyms;\r\n\r\n-- ============================================\r\n-- Limpieza\r\n-- ============================================\r\nBEGIN\r\n    EXECUTE IMMEDIATE 'DROP SYNONYM SYN_PACIENTES_REMOTO';\r\n    EXECUTE IMMEDIATE 'DROP PUBLIC SYNONYM PUBLIC_SYN_PACIENTES';\r\n    DBMS_OUTPUT.PUT_LINE('Sin\xf3nimos eliminados.');\r\nEND;\r\n/\n"})})]})}function t(n={}){const{wrapper:r}={...(0,o.R)(),...n.components};return r?(0,s.jsx)(r,{...n,children:(0,s.jsx)(c,{...n})}):c(n)}},28453(n,r,e){e.d(r,{R:()=>i,x:()=>_});var a=e(96540);const s={},o=a.createContext(s);function i(n){const r=a.useContext(o);return a.useMemo(function(){return"function"==typeof n?n(r):{...r,...n}},[r,n])}function _(n){let r;return r=n.disableParentContext?"function"==typeof n.components?n.components(s):n.components||s:i(n.components),a.createElement(o.Provider,{value:r},n.children)}}}]);